draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // stick figure body
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 60 + 10 * Math.cos(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 10);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t + Math.PI), H/2 + 60 + 10 * Math.cos(t + Math.PI));
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20 + 15 * Math.sin(t + Math.PI/2), H/2 + 80 + 15 * Math.cos(t + Math.PI/2));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20 + 15 * Math.sin(t - Math.PI/2), H/2 + 80 + 15 * Math.cos(t - Math.PI/2));
  ctx.stroke();

  ctx.restore();
}
